/* Generated from assets/spritz-illustration.jpg; generic drink artwork, never a venue photograph. */
/* global window, document, URL */
(() => {
  "use strict";
  const photo =
    "data:image/jpeg;base64,";
  window.__dovebevoDrinkArt = (context) => {
    try {
      const url = new URL(window.location.href);
      if (
        window.top !== window ||
        url.protocol !== "https:" ||
        !["dovebevo.com", "www.dovebevo.com"].includes(url.hostname) ||
        url.username ||
        url.password ||
        (url.port && url.port !== "443") ||
        !/^(?:\/|\/bar\/[nwru][1-9][0-9]{0,14})$/.test(url.pathname) ||
        document.documentElement.getAttribute("data-dovebevo-app-theme") !== "1"
      )
        return;
      const app = document.querySelector("#app > .app");
      if (
        !app ||
        !app.contains(context) ||
        !context.matches("h3.context-tag") ||
        !context.closest("form")?.querySelector(".price-input input")
      )
        return;
      const current = context.querySelector("img.dovebevo-drink-art");
      if (context.textContent.trim().toLowerCase() !== "spritz") {
        if (current) current.remove();
        context.removeAttribute("data-dovebevo-art");
        return;
      }
      if (current) return;
      const picture = document.createElement("img");
      picture.className = "dovebevo-drink-art";
      picture.alt = "";
      picture.width = 1024;
      picture.height = 1536;
      picture.decoding = "async";
      picture.src = photo;
      context.setAttribute("data-dovebevo-art", "spritz");
      context.prepend(picture);
    } catch {
      // Artwork is optional; original drink label and form remain functional.
    }
  };
})();
